package admin

import (
	"context"
	"database/sql"

	"github.com/uptrace/bun"
)

// This file is the READ side of the CIM reference dictionary (migration 0120):
// the full CIM class + attribute complement (metadata.cim_ref_classes /
// cim_ref_attributes, generated by cmd/cimdict from schema/cim/) plus the
// profile-membership layer (cim_ref_profile_members). It exists so the CIM
// mapping editor can offer real CIM class/attribute names -- defaulting to the
// in-profile subset and flagging free text that isn't in the vocabulary at all
// -- instead of the old free-text boxes with no validation or discoverability.
//
// Read-only and additive: it does NOT change what the encoder emits (that is
// still cim_class_mappings + the behavioral Go in api/internal/export). The
// `in_profile` flag on every row is resolved against a profile whose code
// matches a metadata.cim_profiles.code (the export target the editor is working
// in); an empty profile resolves to the default profile, and no default at all
// just means everything comes back in_profile=false (a flat full-CIM reference).

// cimRefClassResponse is one metadata.cim_ref_classes row for the editor's CIM
// class picker/validator: the class name (the natural key a cim_class mapping
// targets), its superclass, whether it is abstract (the editor should steer away
// from abstract targets), a human description, and whether it is in the resolved
// profile's membership set (so the picker can default to the safe subset).
type cimRefClassResponse struct {
	Name        string `json:"name"`
	ParentName  string `json:"parent_name,omitempty"`
	IsAbstract  bool   `json:"is_abstract"`
	Description string `json:"description,omitempty"`
	InProfile   bool   `json:"in_profile"`
}

// cimRefAttributeResponse is one metadata.cim_ref_attributes row for the editor's
// CIM attribute picker/validator, scoped to a chosen CIM class: the attribute
// name (the part after the dot in a ClassName.attribute mapping target), whether
// it is an association (object property) vs a literal attribute, its range and
// multiplicity where the schema states them, a description, and profile membership.
//
// The set is INHERITANCE-AWARE: it includes attributes declared on the class's
// superclasses too, because a CIM instance legitimately carries inherited
// properties. DeclaringClass names the class that actually declares the property
// (which may be an ancestor) and Inherited flags that case -- this matters for
// export because CIM RDF/XML serializes a property under its DECLARING class's
// QName (cim:TapChanger.step, never cim:RatioTapChanger.step), so the editor can
// steer a mapping to the canonical target instead of one a strict consumer drops.
type cimRefAttributeResponse struct {
	Name           string `json:"name"`
	IsAssociation  bool   `json:"is_association"`
	Range          string `json:"range,omitempty"`
	Multiplicity   string `json:"multiplicity,omitempty"`
	Description    string `json:"description,omitempty"`
	DeclaringClass string `json:"declaring_class,omitempty"`
	Inherited      bool   `json:"inherited"`
	InProfile      bool   `json:"in_profile"`
}

// resolveDictProfileCode turns the editor's optional ?profile= into the code the
// membership rows are keyed by. An empty profile falls back to the default
// metadata.cim_profiles row (the export target used when a request names none),
// mirroring how the rest of the CIM code treats an omitted profile. When there
// is no default profile at all it returns "" -- membership then resolves to
// false for every row, so the dictionary still works as a flat full-CIM list.
func resolveDictProfileCode(ctx context.Context, db *bun.DB, profileCode string) (string, error) {
	if profileCode != "" {
		return profileCode, nil
	}
	var code string
	err := db.NewSelect().
		TableExpr("metadata.cim_profiles").
		ColumnExpr("code").
		Where("is_default = true").
		Limit(1).
		Scan(ctx, &code)
	if err != nil {
		if err == sql.ErrNoRows {
			return "", nil
		}
		return "", err
	}
	return code, nil
}

// listCimRefClasses returns every CIM class in the reference dictionary, name-
// ordered, each flagged with whether it is in the resolved profile's membership
// set. The LEFT JOIN keeps out-of-profile classes (in_profile=false) so the
// editor can still offer the wider CIM as an opt-in. Whole-class membership is
// the row with attribute_name IS NULL.
func listCimRefClasses(ctx context.Context, db *bun.DB, profileCode string) ([]cimRefClassResponse, error) {
	resolved, err := resolveDictProfileCode(ctx, db, profileCode)
	if err != nil {
		return nil, err
	}

	var rows []struct {
		Name        string  `bun:"name"`
		ParentName  *string `bun:"parent_name"`
		IsAbstract  bool    `bun:"is_abstract"`
		Description *string `bun:"description"`
		InProfile   bool    `bun:"in_profile"`
	}
	if err := db.NewSelect().
		TableExpr("metadata.cim_ref_classes AS c").
		ColumnExpr("c.name AS name").
		ColumnExpr("c.parent_name AS parent_name").
		ColumnExpr("c.is_abstract AS is_abstract").
		ColumnExpr("c.description AS description").
		ColumnExpr("(m.class_name IS NOT NULL) AS in_profile").
		Join("LEFT JOIN metadata.cim_ref_profile_members AS m ON m.class_name = c.name AND m.attribute_name IS NULL AND m.profile_code = ?", resolved).
		OrderExpr("c.name").
		Scan(ctx, &rows); err != nil {
		return nil, err
	}

	out := make([]cimRefClassResponse, len(rows))
	for i, r := range rows {
		resp := cimRefClassResponse{Name: r.Name, IsAbstract: r.IsAbstract, InProfile: r.InProfile}
		if r.ParentName != nil {
			resp.ParentName = *r.ParentName
		}
		if r.Description != nil {
			resp.Description = *r.Description
		}
		out[i] = resp
	}
	return out, nil
}

// listCimRefAttributes returns the properties (attributes + associations) visible
// on one CIM class -- its own declared attributes PLUS every attribute inherited
// from its superclasses, walked up the parent_name chain -- name-ordered, each
// flagged with its declaring class, whether it is inherited, and profile
// membership. Inheritance matters twice over: a CIM instance really does carry
// its ancestors' properties (so a mapping to an inherited attribute is valid, not
// an error to flag), and CIM RDF/XML serializes each property under its declaring
// class, so the editor needs the declaring class to offer the canonical target.
//
// An unknown class name simply yields an empty list -- not an error -- so the
// editor can offer nothing rather than fail when a mapping targets a class the
// reference dump happens to omit. Where two ancestors both declare a same-named
// attribute (CIM restrictions occasionally re-state one), the nearest class wins
// via DISTINCT ON ordered by ancestry depth.
func listCimRefAttributes(ctx context.Context, db *bun.DB, className, profileCode string) ([]cimRefAttributeResponse, error) {
	resolved, err := resolveDictProfileCode(ctx, db, profileCode)
	if err != nil {
		return nil, err
	}

	var rows []struct {
		Name           string  `bun:"name"`
		IsAssociation  bool    `bun:"is_association"`
		Range          *string `bun:"range"`
		Multiplicity   *string `bun:"multiplicity"`
		Description    *string `bun:"description"`
		DeclaringClass string  `bun:"declaring_class"`
		Inherited      bool    `bun:"inherited"`
		InProfile      bool    `bun:"in_profile"`
	}
	// ancestry = the target class (depth 0) and each superclass above it; the
	// DISTINCT ON keeps the nearest declaration of a same-named attribute, then a
	// final name-order makes the payload stable. Membership is keyed by the
	// attribute's real declaring class (that is how the derive-seed records it).
	const q = `
WITH RECURSIVE ancestry AS (
    SELECT name, parent_name, 0 AS depth
    FROM metadata.cim_ref_classes
    WHERE name = ?
  UNION ALL
    SELECT c.name, c.parent_name, a.depth + 1
    FROM ancestry a
    JOIN metadata.cim_ref_classes c ON c.name = a.parent_name
    WHERE a.depth < 30
)
SELECT name, is_association, range, multiplicity, description,
       declaring_class, inherited, in_profile
FROM (
    SELECT DISTINCT ON (att.name)
        att.name           AS name,
        att.is_association  AS is_association,
        att.range           AS range,
        att.multiplicity    AS multiplicity,
        att.description     AS description,
        att.class_name      AS declaring_class,
        (anc.depth > 0)     AS inherited,
        (m.class_name IS NOT NULL) AS in_profile
    FROM ancestry anc
    JOIN metadata.cim_ref_attributes att ON att.class_name = anc.name
    LEFT JOIN metadata.cim_ref_profile_members m
        ON m.class_name = att.class_name AND m.attribute_name = att.name AND m.profile_code = ?
    ORDER BY att.name, anc.depth
) props
ORDER BY name`
	if err := db.NewRaw(q, className, resolved).Scan(ctx, &rows); err != nil {
		return nil, err
	}

	out := make([]cimRefAttributeResponse, len(rows))
	for i, r := range rows {
		resp := cimRefAttributeResponse{
			Name:           r.Name,
			IsAssociation:  r.IsAssociation,
			DeclaringClass: r.DeclaringClass,
			Inherited:      r.Inherited,
			InProfile:      r.InProfile,
		}
		if r.Range != nil {
			resp.Range = *r.Range
		}
		if r.Multiplicity != nil {
			resp.Multiplicity = *r.Multiplicity
		}
		if r.Description != nil {
			resp.Description = *r.Description
		}
		out[i] = resp
	}
	return out, nil
}
